type App =
	| 'react-boilerplate'
	| 'angular-phonecat'
	| 'killedbygoogle'
	| 'angular-realworld'
	| 'papercups'
	| 'react-hospitalrun'
	| 'angular-factoriolab'
	| 'angular-jira-clone'
	| 'next-killedbygoogle-v3-0-0'
	| 'react-linkfree'
	| 'react-memos'
	| 'angular-tiny-translator';
type Lane = 'baseline' | 'migrated';
type JourneyEvidence = {
	assertions: string[];
	offlineEvidence: WitnessOfflineEvidence;
	timeoutTelemetry?: ServiceWorkerTelemetry;
	zeroServiceWorker?: {
		checkpoints: Array<{
			phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
			state: 'timeout';
			registrations: 0;
			controller: null;
			cacheNames: [];
			workerEvents: [];
		}>;
	};
	/**
	 * Evidence for an application that ATTEMPTS a service-worker registration and
	 * is refused, which is a different fact from an application that never asks.
	 *
	 * The zero-worker shape above asserts an empty observer trace, and an
	 * application whose registration is rejected does not have one: the browser
	 * opens a registration record for the attempt and reports the script it could
	 * not fetch. Folding that into the zero shape would have meant either
	 * asserting something untrue or dropping the assertion, so the attempt gets
	 * its own shape — every settled fact of the zero shape still asserted, plus
	 * the attempt trace recorded exactly rather than required to be absent.
	 */
	refusedServiceWorker?: {
		attempt: { script: string; scopePath: string };
		checkpoints: Array<{
			phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
			state: 'timeout';
			registrations: 0;
			controller: null;
			cacheNames: [];
			attemptEvents: ServiceWorkerTelemetry['workerEvents'];
		}>;
	};
	/**
	 * Runtime zero-service-worker evidence for an application whose legacy build
	 * still emits a worker script it never registers. The emitted bytes are
	 * recorded rather than asserted away, and the runtime is required to show no
	 * registration, controller, CacheStorage name, lifecycle event, or worker
	 * request in any lane.
	 */
	zeroServiceWorkerRuntime?: {
		registration: 'application-unregister';
		checkpoints: Array<{
			phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
			state: 'timeout';
			registrations: 0;
			controller: null;
			cacheNames: [];
			workerEvents: [];
		}>;
	};
	/**
	 * Runtime evidence for an application whose own code calls
	 * `serviceWorker.register()`. The registration is refused at the browser
	 * context, so no worker is ever installed, controls the page, or opens a
	 * cache — and the refusal is not silenced: whatever the application logs in
	 * response is accounted for by the exact console-error inventory.
	 */
	blockedServiceWorkerRuntime?: {
		registration: 'application-register-refused-by-context';
		checkpoints: Array<{
			phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
			state: 'timeout';
			registrations: 0;
			controller: null;
			cacheNames: [];
			workerEvents: [];
		}>;
	};
	/**
	 * Evidence for a lane whose worker genuinely succeeds — the fourth member,
	 * and the first that is not a shape of absence.
	 *
	 * The three shapes above all assert an empty settled state, which is what
	 * makes each of them strong and also what makes none of them usable here: a
	 * worker that installed, activated and took control fails every one of their
	 * assertions. So it gets its own member rather than a relaxation of theirs,
	 * and the existing shapes are untouched. What the journey supplies is the
